eidx = [0]

def get_unique_emoji(used):
    for i in range(len(emojis)):
        e = emojis[(eidx[0] + i) % len(emojis)]
        if e not in used:
            eidx[0] = (eidx[0] + i + 1) % len(emojis)
            used.add(e)
            return e
    # Fallback - use the next emoji
    e = emojis[eidx[0] % len(emojis)]
    eidx[0] += 1
    return e

def assign_emojis(entities):
    if not entities:
        return
    used = set()
    for e in entities:
        desc = e.get('description', '')
        if desc:
            emoji = get_unique_emoji(used)
            e['description'] = emoji + ' ' + desc

# Kit description
