const kit = JSON.parse(kitJson);
newZip.file('kit.json', JSON.stringify(kit, null, 2));

// Copy all other files from original
const entries = Object.entries(origZip.files);
let count = 0;
for (const [name, file] of entries) {
  if (name === 'kit.json') continue;
  if (file.dir) {
    newZip.folder(name);
  } else {
    const data = await file.async('uint8array');
    newZip.file(name, data);
    count++;
  }
}
console.log('Copied', count, 'representation files');

const zipBuffer = await newZip.generateAsync({ type: 'nodebuffer', compression: 'DEFLATE', compressionOptions: { level: 6 } });
writeFileSync('compose/assets/compose/metabolism.zip', zipBuffer);
console.log('Wrote metabolism.zip:', zipBuffer.length, 'bytes');
